package com.openclaw.bot.email;

/**
 * {@code EmailSender} provides the mechanism for delivering alerts generated by the bot.
 * <p>
 * Implementations support multiple delivery mechanisms: live SMTP (for production),
 * a debug sink (for protocol capture/monitoring), or file-based logging (for offline demos).
 * @author OpenClaw Development Team
 */
public interface EmailSender {

  /**
   * Sends the complete alert message to the configured recipient(s).
   * @param subject The subject line of the alert email.
   * @param body The full content body of the alert message.
   * @throws Exception if the delivery mechanism (e.g., network timeout, failed SMTP login) fails.
   */
  void send(String subject, String body) throws Exception;
}
